  /**
   * A resume request that found nothing to restore behaves like a fresh start: the start-up detection it skipped
   * runs now (one request, as autoDetectModel does), and the first request waits for it.
   */
  public detectPlaceholderModel(): Promise<void> {
    if (this.config.provider || this.config.model !== "local-model") return Promise.resolve();
    this.pendingModelDetection = (async () => {
      try {
        const models = await this.client.listModels();
        if (models.length > 0 && this.config.model === "local-model") this.setDefaultModel(models[0]);
      } catch {
        // Keep the placeholder; the request will surface the connection problem.
      }
    })();
    return this.pendingModelDetection;
  }

  /** The deferred detection, once the provider may be asked again: the first model the gateway lists. */
  private async detectDeferredModel(): Promise<void> {
    if (!this.modelDetectionDeferred || this.isProviderWindowOpen()) return;
    this.modelDetectionDeferred = false;
    try {
      const models = await this.client.listModels();
  }

  /**
   * 3 s startup reachability check (`GET /models`, REQ-TUI-105). Returns an actionable warning naming the endpoint,
   * cause and fix (`nexus doctor`, `~/.config/nexus/config.env`, `/connect`) when unreachable or rejected; undefined when ok.
   */
  public async probeStartupEndpoint(signal?: AbortSignal): Promise<string | undefined> {
    if (typeof this.client.probeAvailability !== "function") return undefined;
    // After a resume the hosts probe right after restoring: inside the provider's window nothing is sent. The
    // resumed turn waits it out and re-probes through live recovery, so no warning is lost.
    if (this.isProviderWindowOpen()) return undefined;
    try {
      const probe = await this.client.probeAvailability(signal, { timeoutMs: 3_000 });
      if (probe.available && probe.httpStatus !== undefined && probe.httpStatus >= 200 && probe.httpStatus < 300) {
        this.client.markSucceeded?.(this.client.endpoint);
      }
      return startupEndpointWarning(this.client.endpoint, probe);
    } catch {
      return undefined;
    }
  }

  public setProviderRecoveryHooks(hooks: Pick<RecoveryHooks<unknown>, "onFailure" | "shouldYield"> | undefined): void {
    this.providerRecoveryHooks = hooks;
  }

  private onProviderRecoveryState(
    record: ProviderRecoveryRecord,
    turn: NonNullable<AutonomousAgent["activeTurn"]>,
    discardedPartialOutput: boolean,
  ): void {

export interface ModelSummary {
  summary: string;
  notes?: string;
}

export type SidecarEvent =
  | { type: "hello"; protocol: number; pid: number; commands: Array<Pick<SlashSpec, "name" | "usage" | "summary">> }
  | {
      type: "session.state";
      workspace: string;
      workspace_name: string;
      model: string;
      mode: "auto" | "review" | "read-only";
      git: { branch: string; dirty: number } | null;
      busy: boolean;
      /** The id the session is saved under (shown so it can be resumed or referred to). */
      session?: string;
      /** The same facts the REPL /status reports (gate I-3). */
      read_only?: boolean;
      context_tokens?: number;
      context_limit?: number;
      endpoint_kind?: "local" | "cloud";
      posture?: {
        mode: "auto" | "review" | "read-only";
        sandbox: string;
        trusted: boolean;
      };
    }
  | { type: "assistant.delta"; turn_id: string; text: string }
  /** What the running turn is doing; sent on every phase change, independent of model output. */
  | {
      type: "activity";
      turn_id: string;
      phase: string;
      step: number;
      segment: number;
      tool?: string;
      subject?: string;
      /** The turn's budget: total steps across segments, and the wall-clock limit in minutes (when continuation is on). */
      max_steps?: number;
      this.onShutdown();
    })();
    return this.shutdownPromise;
  }

  private emitSessionState(): void {
    const config = this.app.getConfig();
    const facts = surfaceFacts(this.app, this.sessionId);
    const git = getGitInfo(config.workspace);
    const trusted = isWorkspaceTrusted(config.workspace, Boolean(config.readOnly));
    const sandboxStatus = config.sandbox ? (typeof config.sandbox === "string" ? config.sandbox : "on") : "off";
    this.emit({
      type: "session.state",
      workspace: config.workspace,
      workspace_name: path.basename(config.workspace),
      model: facts.model,
      mode: facts.mode,
      git: git.isRepo ? { branch: git.branch, dirty: git.dirtyCount } : null,
      busy: Boolean(this.activeTurn),
      session: facts.session,
      read_only: facts.read_only,
      context_tokens: facts.context_tokens,
      context_limit: facts.context_limit,
      endpoint_kind: facts.endpoint_kind,
      posture: {
        mode: facts.mode,
        sandbox: sandboxStatus,
        trusted,
      },
    });
  }

  private emit(event: SidecarEvent): void {
    const safe = formatSafeSidecarEvent(event);
    if (safe) this.write(encodeEvent(safe));
  }
}

/** Commands that may run while a turn is in progress: diagnosis without repairs. */
function busySafe(command: string, args: string): boolean {
  const name = command.trim().replace(/^\//, "").toLowerCase();
  return name === "doctor" && !args.split(/\s+/).includes("--fix");
}

