  return problem.kind === "unreachable"
    ? `Endpoint ${problem.endpoint} is unreachable${problem.detail ? ` (${problem.detail})` : ""}. Run \`nexus doctor\`, check LOCAL_LLM_ENDPOINT in ~/.config/nexus/config.env, or use /connect.`
